import unittest

from davidkhala.llm.gemini import Client

from davidkhala.ibm.bob.onprem.gemini import from_service_account_info


class BobOnpremTest(unittest.TestCase):
    def setUp(self):
        # Service-account JSON, base64-encoded, single line
        GEMINI_CREDENTIALS = ""
        print()
        print(GEMINI_CREDENTIALS)
        print()

        self.client = Client(from_service_account_info(GEMINI_CREDENTIALS))

    def test_chat(self):
        self.client.as_chat('gemini-3.6-flash')
        r = self.client.chat('How does AI work?')
        print(r)


if __name__ == '__main__':
    unittest.main()
